import csv,io,json,sys
from pathlib import Path
root=Path(sys.argv[1]);out=Path(sys.argv[2]);out.mkdir(parents=True,exist_ok=True)
v=json.loads((root/'inputs.json').read_text());summary=v['summary'];rows=v['concrete_original_anchors'];a=v['completion_audit'];new=next(r for r in summary['rows'] if r['dataset']=='concrete')
assert len(rows)==20 and len(summary['rows'])==5 and new['independent_max_absolute_discrepancy']==0
text=io.StringIO();writer=csv.DictWriter(text,fieldnames=['family','anchor_id','original_V_NMSE','new_followup_V_NMSE']);writer.writeheader()
for row in rows:writer.writerow(dict(family=row['family'],anchor_id=row['anchor_id'],original_V_NMSE=row['V_group_day_NMSE'],new_followup_V_NMSE=repr(new['V_score']) if row['family']=='P12' else ''))
(out/'concrete.csv').write_text(text.getvalue())
(out/'concrete-summary.json').write_text(json.dumps(summary,indent=2,sort_keys=True)+'\n')
grown=float(next(r['V_group_day_NMSE'] for r in rows if r['family']=='P00'));cat=float(next(r['V_group_day_NMSE'] for r in rows if r['family']=='P08'));benefit=1-new['V_score']/grown
lines=['# Native anchor follow-up: Concrete NODE','',f"Full native NODE has primary Concrete validation NMSE **{new['V_score']:.9f}**, versus the grown cheap-placement anchor **{grown:.9f}** and CatBoost **{cat:.9f}**. Lower is better. NODE’s point error is {100*benefit:.2f}% lower than grown; CatBoost remains lower than both. This is one fixed native setting/split/seed, not a tuned or protected-test comparison.",'','The [predeclared five-cell follow-up](../docs/research/v2/native-anchor-development-appendix.md) includes every completed cell regardless of validation outcome. This immutable tranche adds Concrete and rechecks the already scored Airfoil value exactly. It preserves the original 115-score survey and earlier Airfoil tranche. Native engineering completions now number 117 of 120; Parkinsons is running, with CCPP and Bike following serially. Energy was in the original survey.','', '| Fixed follow-up cell | Status | V NMSE |','|---|---|---:|']
for row in summary['rows']:
 score='—' if row['V_score'] is None else format(row['V_score'],'.9f');lines.append(f"| {row['dataset']} | {row['status'].replace('_',' ')} | {score} |")
lines+=['','All twenty Concrete anchor coordinates remain visible. Existing values come from the unchanged original survey; only P12 receives a newly available score. P13 is the mean anchor, rather than its full 29-configuration reference family.','','| Family / anchor | Original V NMSE | New follow-up V NMSE |','|---|---:|---:|']
for row in rows:
 old=row['V_group_day_NMSE'];old='unavailable' if old in ('','None') else format(float(old),'.9f');fresh=format(new['V_score'],'.9f') if row['family']=='P12' else '—';lines.append(f"| {row['family']} / {row['anchor_id']} | {old} | {fresh} |")
lines+=['',f"The native procedure with 2,048 trees, depth 6 and three output channels executed {a['executed_updates']:,} updates, selected update {a['selected_step']:,} and completed {a['native_G_evaluations']} G evaluations. Native patience and all {a['trace_reference']['rows_updated']:,} applied row visits were independently checked from recorded traces. The audit replays selected predictions exactly; it does not repeat training, RNG transitions or weight updates.",'',f"Containing execution took {a['containing_elapsed_ns']/1e9:.3f} seconds, about {a['containing_elapsed_ns']/3.6e12:.2f} hours, with {a['observed_peak_root_rss_bytes']:,} bytes sampled peak root-worker RSS ({a['observed_peak_root_rss_bytes']/1024**3:.2f} GiB). It used {a['trainable_parameters']:,} trainable and {a['total_parameters']:,} total parameters on eight encoded features and 577 F rows. Audit time was {a['audit_elapsed_ns']/1e9:.3f} seconds and is separate. These contended timers are not deployment performance or an efficiency comparison. No wall cap, data subsampling, reduced tree count or reduced native effective batch was used.",'',f"Primary V contains {new['V_rows']} rows in {new['V_groups']} mixture groups; group-weighted normalized MSE uses the F target variance with ddof=0. A separate raw fsum calculation agrees exactly on all seven risk metrics and F variance. Row-weighted RMSE is {new['metrics']['row_RMSE']:.6f}; group-weighted RMSE is {new['metrics']['primary_RMSE']:.6f}. No repeat interval or independent dataset-population claim follows.",'',"The producer remains at held source `c33a84e` / package `b680a26b...a65cc`. Engineering eligibility flags remain false; no model migration or extra fitting occurred for this scoring. The current coordinator’s source and before/after byte bindings are retained. T stays sealed, secondary development remains unavailable, and M3’s negative Gate B stays closed.",'',"[All 20 Concrete points](../audit/research-v2/native-anchor-follow-up/concrete.csv), [complete five-cell snapshot](../audit/research-v2/native-anchor-follow-up/concrete-summary.json), [completion/scoring receipt](../docs/research/v2/WP07-NODE-Concrete-completion-and-V-receipt.json), [unchanged Airfoil tranche](research-v2-native-anchors-follow-up.md). Full common-source native qualification, HPO, global freeze and protected evaluation remain unfinished."]
(out/'research-v2-native-anchors-concrete.md').write_text('\n'.join(lines)+'\n')
